### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, k;
        string s;
        cin >> n >> k >> s;

        // 1) 构造前缀字符计数 cnt[i][d] 和最大字母索引 max_letter[i]
        vector<array<int, 26>> cnt(n + 1);
        vector<int> max_letter(n + 1, -1);
        for (int i = 1; i <= n; ++i) {
            cnt[i] = cnt[i - 1];
            int c = s[i - 1] - 'a';
            cnt[i][c]++;
            max_letter[i] = max(max_letter[i - 1], c);
        }

        // 2) 创建下标数组并自定义排序
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 1);
        sort(idx.begin(), idx.end(), [&](int i, int j) {
            for (int d = 0; d < 26; ++d) {
                int ci = cnt[i][d], cj = cnt[j][d];
                if (ci != cj) {
                    if (ci > cj) {
                        // i 在字母 d 上比 j 多
                        if (max_letter[j] > d) return true;  // t_i < t_j
                        else return false;                   // t_j < t_i
                    } else { // ci < cj
                        if (max_letter[i] > d) return false; // t_i > t_j
                        else return true;                    // t_i < t_j
                    }
                }
            }
            // 所有字母次数相同时，下标小的在前
            return i < j;
        });

        // 3) 取第 k 小的起始片段下标
        int p = idx[k - 1];

        // 4) 根据 cnt[p] 重建并输出整理后片段
        string ans;
        ans.reserve(n);
        for (int d = 0; d < 26; ++d) {
            ans.append(cnt[p][d], char('a' + d));
        }
        cout << ans << "\n";
    }
    return 0;
}
